=== H5HostKindling
<!-- H5 Host, Kindling (sun mode). The flame grows with each yes; only the count (BR-Q-5). Text yes and Cancel (SRS-CH-5). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import CountRing from "../components/CountRing.svelte";
  import Sheet from "../components/Sheet.svelte";
  import TextField from "../components/TextField.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { Theme } from "../components/parts";
  let {
    photo = "",
    scene = "",
    view = "growing",
    theme = "sun",
    have = 1,
    quorum = 2,
    sentMin = 0,
    shrinkMin = null,
    hostLine = "",
    code = "",
    textYesUsed = 0,
    savedAt = "",
    error = "",
    busy = false,
    ontextyes,
    oncancel,
    onshare,
    onclose,
  }: {
    /** The Flare photo behind the screen (2026 direction); the warm light when there is none. */
    photo?: string;
    scene?: string;
    view?: "zero" | "growing" | "near" | "offline" | "text-yes" | "cancel";
    theme?: Theme;
    have?: number;
    quorum?: number;
    sentMin?: number;
    shrinkMin?: number | null;
    hostLine?: string;
    code?: string;
    textYesUsed?: number;
    savedAt?: string;
    error?: string;
    busy?: boolean;
    ontextyes?: (code: string) => void;
    oncancel?: () => void;
    onshare?: () => void;
    onclose?: () => void;
  } = $props();
  // svelte-ignore state_referenced_locally
  let sheet = $state<"" | "text-yes" | "cancel">(view === "text-yes" || view === "cancel" ? view : "");
  let reply = $state("");
</script>

<Screen {theme} sound {onclose} heading={t("host.kindling.heading")} title={t("host.kindling.title")} offline={savedAt ? t("app.offline", { time: savedAt }) : ""} stage backdrop={photo} backdropAlt={scene} fallbackArt>
  {#snippet hero()}
    <div class="center">
      <CountRing {have} {quorum} size={190} />
      <p class="t-muted">{shrinkMin === null || have <= 1 ? (sentMin < 1 ? t("host.kindling.justSent") : t("host.kindling.sentAgo", { min: sentMin })) : t("host.kindling.shrinkIn", { min: shrinkMin })}</p>
    </div>
  {/snippet}
  {#if hostLine}<p class="hostline t-small">{hostLine}</p>{/if}
  {#if error}<p class="err" role="alert">{error}</p>{/if}
  {#snippet actions()}
    <div class="row">
      <Button variant="secondary" icon="share" onclick={onshare}>{t("sent.shareAgain")}</Button>
      <Button variant="secondary" onclick={() => (sheet = "text-yes")}>{t("host.textYes.open")}</Button>
    </div>
    <Button variant="text" onclick={() => (sheet = "cancel")}>{t("host.kindling.cancel")}</Button>
  {/snippet}
  {#snippet overlay()}
    {#if sheet === "cancel"}
      <Sheet inline title={t("host.cancel.title")} description={t("host.cancel.body")}>
        <Button variant="danger" loading={busy} onclick={() => { sheet = ""; oncancel?.(); }}>{t("host.cancel.yes")}</Button>
        <Button variant="text" onclick={() => (sheet = "")}>{t("host.cancel.no")}</Button>
      </Sheet>
    {:else if sheet === "text-yes"}
      <Sheet inline title={t("host.textYes.open")}>
        {#if textYesUsed >= 3}
          <p role="status">{t("host.textYes.max")}</p>
        {:else}
          <TextField label={t("host.textYes.label")} bind:value={reply} hint={t("host.textYes.hint", { code })} max={12} />
          <Button loading={busy} disabled={!reply.trim()} onclick={() => { ontextyes?.(reply); reply = ""; sheet = ""; }}>{t("host.textYes.add")}</Button>
        {/if}
        <Button variant="text" onclick={() => (sheet = "")}>{t("app.close")}</Button>
      </Sheet>
    {/if}
  {/snippet}
</Screen>

<style>
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 8px; }
  .center p { margin: 0; }
  /* Fresh-eyes #14: the status line sits on a dark backing so it reads on any photo or drawing. */
  .center > p { padding: 6px 14px; border-radius: 999px; background: rgb(0 0 0 / 0.45); color: #fff; }
  .hostline { margin: 0; text-align: center; color: var(--text-muted); font-weight: 700; }
  .row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .err { font-weight: 700; margin: 0; text-align: center; }
</style>
=== H6HostLit
<!-- H6 Host, Lit (sun mode). Arrivals and +1 (BR-H-1 to -5). Done ends it for everyone (BR-F-5). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import Hearth from "../components/Hearth.svelte";
  import Sheet from "../components/Sheet.svelte";
  import Icon from "../components/Icon.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { Theme } from "../components/parts";
  let {
    view = "lit",
    theme = "sun",
    coming = 1,
    spot = "",
    here = 0,
    members = [],
    marked = [],
    error = "",
    busy = false,
    onplusone,
    ontell,
    ondone,
    onclose,
  }: {
    view?: "lit" | "arrivals" | "plusone" | "done";
    theme?: Theme;
    coming?: number;
    spot?: string;
    here?: number;
    members?: { id: string; name: string }[]; // names opened on this phone; only the host sees them
    marked?: string[];
    error?: string;
    busy?: boolean;
    onplusone?: (who: { id: string } | "someone_else") => void;
    /** Automations: tell the group chat it's on (share sheet, or copy). */
    ontell?: () => void;
    ondone?: () => void;
    onclose?: () => void;
  } = $props();
  // svelte-ignore state_referenced_locally
  let sheet = $state<"" | "plusone" | "done">(view === "plusone" || view === "done" ? view : "");
</script>

<Screen {theme} sound {onclose} title={t("host.lit.title")} stage fallbackArt>
  {#snippet hero()}
  <div class="center">
    <Hearth state="lit" size={210} celebrate={view === "lit"} />
    <h1 class="t-display">{t("host.lit.headline")}</h1>
    {#if spot}<p class="t-sun">{t("host.lit.coming", { n: coming, spot })}</p>{/if}
  </div>
  {/snippet}
  <div class="here" aria-live="polite">
    <span class="t-heading">{t("host.lit.here", { n: here })}</span>
    <Button variant="secondary" icon="plusone" full={false} onclick={() => (sheet = "plusone")}>{t("host.lit.addOne")}</Button>
  </div>
  {#if error}<p class="err" role="alert">{error}</p>{/if}
  {#snippet actions()}
    <Button onclick={() => (sheet = "done")}>{t("host.lit.done")}</Button>
    {#if ontell}<Button variant="text" icon="share" onclick={ontell}>{t("host.lit.tell")}</Button>{/if}
  {/snippet}
  {#snippet overlay()}
    {#if sheet === "plusone"}
      <Sheet inline title={t("host.plus.title")} description={t("host.plus.body")}>
        <ul class="names">
          {#each members as m (m.id)}
            {@const on = marked.includes(m.id)}
            <li><button class="row" aria-pressed={on} disabled={on || busy} onclick={() => onplusone?.({ id: m.id })}><span>{m.name}</span>{#if on}<Icon name="here" />{/if}</button></li>
          {/each}
          <li><button class="row" disabled={busy} onclick={() => onplusone?.("someone_else")}><span>{t("host.plus.someone")}</span><Icon name="plusone" /></button></li>
        </ul>
        <Button variant="text" onclick={() => (sheet = "")}>{t("app.close")}</Button>
      </Sheet>
    {:else if sheet === "done"}
      <Sheet inline title={t("host.done.title")} description={t("host.done.body")}>
        <Button loading={busy} onclick={() => { sheet = ""; ondone?.(); }}>{t("host.done.yes")}</Button>
        <Button variant="text" onclick={() => (sheet = "")}>{t("host.done.no")}</Button>
      </Sheet>
    {/if}
  {/snippet}
</Screen>

<style>
  .center { text-align: left; align-items: flex-start; }
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 8px; }
  .center h1, .center p { margin: 0; max-width: 24ch; }
  .here { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 14px; border-radius: var(--r-md); background: var(--surface); border: 2px solid var(--line); }
  .names { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
  .row { width: 100%; min-height: 52px; display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; border-radius: var(--r-md); border: 2px solid var(--line); background: var(--surface); color: var(--text); font: inherit; font-weight: 700; }
  .row[aria-pressed="true"] { border-color: var(--lit); }
  .err { font-weight: 700; margin: 0; text-align: center; }
</style>
=== I1Invite
<!-- I1 Invite: what a friend sees from the link. One button, private, no No (SRS-RES-1, -5, -8). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import CountRing from "../components/CountRing.svelte";
  import InfoLines from "../components/InfoLines.svelte";
  import Icon from "../components/Icon.svelte";
  import Tip from "../components/Tip.svelte";
  import Flame from "../components/Flame.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { InviteInfo, Theme } from "../components/parts";
  let {
    view = "kindling",
    theme = "light",
    info = null,
    have = 1,
    quorum = 2,
    error = "",
    busy = false,
    sample = false,
    canCondition = true,
    onyes,
    oncondition,
    onclose,
  }: {
    view?: "kindling" | "loading" | "missing-key" | "lit" | "gone";
    theme?: Theme;
    info?: InviteInfo | null;
    have?: number;
    quorum?: number;
    error?: string;
    busy?: boolean;
    sample?: boolean;
    canCondition?: boolean;
    onyes?: () => void;
    oncondition?: () => void;
    onclose?: () => void;
  } = $props();
  const host = $derived(info?.host ?? "");
  const where = $derived(
    info
      ? info.walkMin !== null
        ? t("invite.whereWalk", { host, spot: info.spot, walk: t("invite.walk", { min: info.walkMin }) })
        : t("invite.where", { host, spot: info.spot })
      : "",
  );
</script>

<Screen {theme} sound {onclose} title={host ? t("invite.title", { host }) : ""} heading={view === "loading" ? t("app.loading") : ""}
  stage={(view === "kindling" || view === "lit") && !!info} backdrop={info?.photo ?? ""} backdropAlt={info?.scene ?? ""}>
  {#snippet hero()}
    {#if info && (view === "kindling" || view === "lit")}
      <h1 class="t-invite words">{info.words}</h1>
    {/if}
  {/snippet}
  {#if view === "loading"}
    <div class="skeleton print-sk" aria-hidden="true"></div>
    <div class="skeleton line" aria-hidden="true"></div>
    <div class="skeleton line short" aria-hidden="true"></div>
  {:else if view === "missing-key"}
    <div class="center">
      <Icon name="warning" size={48} />
      <h1 class="t-title">{t("invite.missingKey")}</h1>
      {#if host}<p class="t-muted">{t("invite.missingKeyHelp", { host })}</p>{/if}
    </div>
  {:else if view === "gone"}
    <div class="center">
      <Flame state="gone" size={120} />
      <h1 class="t-title">{t("gone.title")}</h1>
      <p class="t-muted">{t("gone.body")}</p>
    </div>
  {:else if info}
    <Tip id="invite" text="tip.invite" />
    <div class="where">
      <Icon name="hotspots" size={22} />
      <div>
        <p>{where}</p>
        {#if info.met}
          <p class="spark t-small"><Icon name="spark" size={18} /><span>{t("invite.metHere", { n: info.met.times })}{#if info.met.line} {t("invite.sparkQuote", { line: info.met.line })}{/if}</span></p>
        {/if}
      </div>
    </div>
    <CountRing {have} {quorum} lit={view === "lit"} />
    <InfoLines access={info.access} nature={info.nature} compact />
    {#if error}<p class="err" role="alert">{error}</p>{/if}
  {/if}
  {#snippet actions()}
    {#if (view === "kindling" || view === "lit") && info}
      <Button icon="here" haptic="tap" loading={busy} onclick={onyes}>{t("invite.yes")}</Button>
      {#if canCondition}<Button variant="text" onclick={oncondition}>{t("invite.condition")}</Button>{/if}
    {:else if view === "missing-key" || view === "gone"}
      <Button variant="secondary" onclick={onclose}>{t("gone.close")}</Button>
    {/if}
  {/snippet}
</Screen>

<style>
  .words { margin: 0; font-size: calc(2.5rem * var(--text-scale)); line-height: 1.08; max-width: 14ch; }
  .where { display: flex; gap: 8px; align-items: flex-start; }
  .where p { margin: 0; }
  .spark { display: flex; gap: 6px; align-items: center; color: var(--accent-text); font-weight: 700; margin-top: 4px !important; }
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; text-align: center; }
  .center h1, .center p { margin: 0; max-width: 22ch; }
  .err { margin: 0; color: var(--text); font-weight: 700; }
  .skeleton { background: color-mix(in srgb, var(--text) 9%, transparent); border-radius: var(--r-md); animation: pulse 1.4s var(--ease-in-out) infinite; }
  .print-sk { height: 300px; }
  .line { height: 32px; }
  .short { width: 60%; }
  @keyframes pulse { 50% { opacity: 0.55; } }
  @media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }
</style>
=== I6Lit
<!-- I6 Lit (sun mode): host line, spot, walk, access and nature lines, Find them, I'm here (SRS-LIT-2). Works offline (SRS-OFF-2). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import Hearth from "../components/Hearth.svelte";
  import InfoLines from "../components/InfoLines.svelte";
  import Sheet from "../components/Sheet.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { InviteInfo, Theme } from "../components/parts";
  let {
    together = null,
    view = "lit",
    theme = "sun",
    info,
    savedAt = "",
    smallerAt = "",
    cant = false,
    error = "",
    busy = false,
    onfind,
    onhere,
    oncant,
    onclose,
  }: {
    /** Minutes outside together once 2+ have arrived (2026 direction, B). */
    together?: number | null;
    view?: "lit" | "offline" | "smaller";
    theme?: Theme;
    info: InviteInfo;
    savedAt?: string; // "2:14 PM" when the screen is from the offline copy
    smallerAt?: string; // the Ember bench name when the Flare got smaller
    cant?: boolean; // this person said "Can't make it"
    error?: string;
    busy?: boolean;
    onfind?: () => void;
    onhere?: () => void;
    oncant?: () => void;
    onclose?: () => void;
  } = $props();
  let asking = $state(false);
</script>

<Screen {theme} sound {onclose} title={t("lit.title", { host: info.host })} offline={savedAt ? t("app.offline", { time: savedAt }) : ""} stage backdrop={info.photo} backdropAlt={info.scene}>
  {#snippet hero()}
  <div class="center">
    <Hearth state="lit" size={190} celebrate={view === "lit" && !savedAt} />
    {#if view === "smaller" && smallerAt}
      <h1 class="t-title">{t("ember.headline", { bench: smallerAt })}</h1>
    {:else}
      <h1 class="t-display">{t("lit.headline")}</h1>
      <p class="t-sun">{info.hostLine}</p>
    {/if}
    {#if together !== null}<p class="together">{t("lit.together", { min: together })}</p>
    {:else if info.walkMin !== null}<p class="t-muted">{t("invite.walk", { min: info.walkMin })}</p>{/if}
    {#if cant}<p class="t-muted" role="status">{t("lit.cantDone")}</p>{/if}
    {#if error}<p class="err" role="alert">{error}</p>{/if}
  </div>
  {/snippet}
  <InfoLines access={info.access} nature={info.nature} />
  {#snippet actions()}
    <Button icon="compass" onclick={onfind}>{t("lit.find")}</Button>
    <div class="row">
      <Button variant="secondary" icon="here" loading={busy} onclick={onhere}>{t("lit.here")}</Button>
      {#if !cant}<Button variant="text" onclick={() => (asking = true)}>{t("lit.cant")}</Button>{/if}
    </div>
  {/snippet}
  {#snippet overlay()}
    {#if asking}
      <Sheet inline title={t("lit.cantSheet.title")} description={t("lit.cantSheet.body")}>
        <Button variant="secondary" onclick={() => { asking = false; oncant?.(); }}>{t("lit.cantSheet.yes")}</Button>
        <Button variant="text" onclick={() => (asking = false)}>{t("lit.cantSheet.no")}</Button>
      </Sheet>
    {/if}
  {/snippet}
</Screen>

<style>
  .together { margin: 0; font-weight: 700; color: var(--c-gold-400); }
  .center { text-align: left; align-items: flex-start; }
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 6px; }
  .center h1, .center p { margin: 0; max-width: 22ch; }
  .row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; align-items: center; }
  .err { font-weight: 700; }
</style>
=== I9Ember
<!-- I9 Ember (sun mode): it didn't catch, so it shrinks to a bench close by. One friend is enough (BR-E-1 to -5). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import Hearth from "../components/Hearth.svelte";
  import FlameMeter from "../components/FlameMeter.svelte";
  import InfoLines from "../components/InfoLines.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { InviteInfo, Theme } from "../components/parts";
  let {
    view = "waiting",
    theme = "sun",
    info,
    bench,
    meters = null,
    have = 1,
    answered = false,
    error = "",
    busy = false,
    onyes,
    onfind,
    onclose,
  }: {
    view?: "waiting" | "lit";
    theme?: Theme;
    info: InviteInfo;
    bench: string; // Ember place name ("the bench by the lot"); the spot itself when none qualified
    meters?: number | null; // from the spot
    have?: number;
    answered?: boolean;
    error?: string;
    busy?: boolean;
    onyes?: () => void;
    onfind?: () => void;
    onclose?: () => void;
  } = $props();
  const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
</script>

<Screen {theme} sound {onclose} title={t("lit.title", { host: info.host })} stage backdrop={info.photo} backdropAlt={info.scene}>
  {#snippet hero()}
  <div class="center">
    <Hearth state={view === "lit" ? "lit" : "ember"} size={150} celebrate={view === "lit"} />
    <h1 class="t-title">{view === "lit" ? t("lit.notice", { host: info.host, spot: bench }) : t("ember.headline", { bench })}</h1>
    {#if meters !== null}<p class="t-muted">{t("ember.where", { Bench: cap(bench), m: meters, spot: info.spot })}</p>{/if}
    {#if error}<p class="err" role="alert">{error}</p>{/if}
  </div>
  {/snippet}
  {#if view !== "lit"}<FlameMeter state="ember" {have} quorum={2} note={t("ember.meterNote")} />{/if}
  <InfoLines access={info.access} nature={info.nature} />
  {#snippet actions()}
    {#if view === "lit"}
      <Button icon="compass" onclick={onfind}>{t("lit.find")}</Button>
    {:else if !answered}
      <Button icon="here" haptic="tap" loading={busy} onclick={onyes}>{t("invite.yes")}</Button>
    {/if}
  {/snippet}
</Screen>

<style>
  .center { text-align: left; align-items: flex-start; }
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 8px; }
  .center h1, .center p { margin: 0; max-width: 22ch; }
  .err { font-weight: 700; }
</style>
=== I10Gone
<!-- I10 Not this time: the same words for everyone (SRS-ST-3). Smoke drifts away. -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import Hearth from "../components/Hearth.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { Theme } from "../components/parts";
  let { theme = "light", onclose }: { theme?: Theme; onclose?: () => void } = $props();
</script>

<Screen {theme} close={false}>
  <div class="center">
    <Hearth state="gone" size={170} />
    <h1 class="t-display">{t("gone.title")}</h1>
    <p>{t("gone.body")}</p>
